records.command:
$ErrorActionPreference = 'Stop'
$env:NPM_CONFIG_CACHE = Join-Path (Get-Location) '.cache/npm'
foreach($spec in @('@tauri-apps/api@2.10.1','@tauri-apps/cli@2.10.0','vite@7.3.1','@vitejs/plugin-react@5.1.2')){
  Write-Output "PACKAGE=$spec"
  & npm.cmd view $spec version engines peerDependencies deprecated --json --registry=https://registry.npmjs.org
  $code=$LASTEXITCODE
  Write-Output "METADATA_EXIT=$code"
  if($code -ne 0){exit $code}
}
exit 0

